import * as XLSX from 'xlsx';
import { supabase } from './supabase';
import { GoogleGenAI } from '@google/genai';

// Instancia o cliente do Gemini
// A chave deve estar no arquivo .env (VITE_GEMINI_API_KEY)
const apiKey = import.meta.env.VITE_GEMINI_API_KEY;
const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

// Esquema JSON esperado pela LLM (Structured Outputs)
const schema = {
  type: "OBJECT",
  properties: {
    secretaria: {
      type: "STRING",
      description: "Nome da Secretaria ou 'NÃO IDENTIFICADO'"
    },
    unidade: {
      type: "STRING",
      description: "Nome do equipamento, escola ou unidade ou 'NÃO IDENTIFICADO'"
    },
    motivo: {
      type: "STRING",
      description: "Categoria em CAIXA ALTA (ex: EQUIPAMENTO, CADASTRO, SISTEMA, SUPORTE, MANUTENÇÃO)"
    }
  },
  required: ["secretaria", "unidade", "motivo"]
};

const SYSTEM_INSTRUCTION = `Você é um assistente encarregado de classificar chamados técnicos.
Analise o TÍTULO e a DESCRIÇÃO fornecidos e extraia os campos em formato JSON estrito:

Responda estritamente no seguinte formato JSON:
{
  "secretaria": "Nome da Secretaria ou 'NÃO IDENTIFICADO'",
  "unidade": "Nome do equipamento, escola ou unidade ou 'NÃO IDENTIFICADO'",
  "motivo": "Categoria em CAIXA ALTA (ex: EQUIPAMENTO, CADASTRO, SISTEMA, SUPORTE, MANUTENÇÃO)"
}`;

/**
 * Lê o arquivo e retorna as linhas como objetos JSON
 */
export async function lerArquivoPlanilha(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: '' });
        resolve(jsonData);
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = (err) => reject(err);
    reader.readAsArrayBuffer(file);
  });
}

/**
 * Faz a chamada para a LLM (Gemini) para classificar o chamado
 */
async function classificarChamadoLLM(titulo, descricao) {
  if (!ai) {
    throw new Error('Chave VITE_GEMINI_API_KEY não configurada no arquivo .env');
  }

  const prompt = `Título: ${titulo}\nDescrição: ${descricao}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-pro',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: 'application/json',
        responseSchema: schema,
      }
    });

    const resultText = response.text; // Fixed response text getter
    return JSON.parse(resultText);
  } catch (error) {
    console.error('Erro ao classificar com LLM:', error);
    return {
      secretaria: 'NÃO IDENTIFICADO',
      unidade: 'NÃO IDENTIFICADO',
      motivo: 'NÃO IDENTIFICADO'
    };
  }
}

/**
 * Processa a lista de chamados, envia para LLM, e salva no Supabase
 * Recebe callback de progresso (opcional)
 */
export async function processarEImportarChamados(linhas, onProgress) {
  const chamadosParaInserir = [];
  
  for (let i = 0; i < linhas.length; i++) {
    const row = linhas[i];
    
    // Ignora linhas vazias ou sem código
    if (!row['CÓDIGO'] && !row['CÓDIGO ']) continue;
    
    const codigoStr = String(row['CÓDIGO'] || row['CÓDIGO '] || '').replace(/\D/g, '');
    const ticket = parseInt(codigoStr, 10);
    
    if (isNaN(ticket)) continue;

    // Extrair dados básicos
    let dataAberturaRaw = row['DATA ABERTURA'] || row['DATA DE CADASTRO'] || null;
    let data_abertura = null;
    
    if (dataAberturaRaw) {
        // Lida com datas no formato DD/MM/YYYY ou formato de serial do Excel
        if (typeof dataAberturaRaw === 'number') {
           const date = XLSX.SSF.parse_date_code(dataAberturaRaw);
           data_abertura = `${date.y}-${String(date.m).padStart(2, '0')}-${String(date.d).padStart(2, '0')}`;
        } else if (typeof dataAberturaRaw === 'string') {
            const parts = dataAberturaRaw.split(/[\/\s-]/);
            if (parts.length >= 3 && parts[0].length <= 2) { // DD/MM/YYYY
                data_abertura = `${parts[2]}-${parts[1]}-${parts[0]}`;
            } else {
                // Tenta fazer parse direto
                const d = new Date(dataAberturaRaw);
                if (!isNaN(d)) data_abertura = d.toISOString().split('T')[0];
            }
        }
    }

    const titulo = row['TITULO'] || row['TÍTULO'] || '';
    const descricao = row['DESCRIÇÃO'] || row['DESCRICAO'] || '';
    const status = row['STATUS'] || 'Aguardando Atendimento';
    
    // Classificação via LLM
    const { secretaria, unidade, motivo } = await classificarChamadoLLM(titulo, descricao);

    chamadosParaInserir.push({
      ticket,
      data_abertura,
      secretaria,
      unidade,
      problema: descricao,
      motivo,
      status
    });

    if (onProgress) {
      onProgress(i + 1, linhas.length);
    }
  }

  // Realiza o Upsert no Supabase em lotes para não sobrecarregar
  const BATCH_SIZE = 50;
  let successCount = 0;

  for (let i = 0; i < chamadosParaInserir.length; i += BATCH_SIZE) {
    const batch = chamadosParaInserir.slice(i, i + BATCH_SIZE);
    const { error } = await supabase
      .from('chamados')
      .upsert(batch, { onConflict: 'ticket' });
      
    if (error) {
      console.error('Erro no upsert:', error);
      throw error;
    }
    successCount += batch.length;
  }

  return successCount;
}
